28	
29	static void* gLibHandle = nullptr;
30	static int gHcommVersion = 0;
31	
32	int GetHcommVersion(void)
33	{
34	    if (gHcommVersion == 0) {
35	        char hcommPkgName[] = "hcomm";
36	        if (aclsysGetVersionNum(hcommPkgName, &gHcommVersion) != ACL_SUCCESS) {
37	            gHcommVersion = 0;
38	        }
39	    }
40	
41	    return gHcommVersion;
42	}
43	
44	bool HcommIsProfilingSupported()
45	{
46	    if (GetHcommVersion() >= CANN_VERSION(9, 0, 0)) {
47	        return true;
48	    } else {
49	        return false;
50	    }
51	}
52	
53	bool HcommIsExportThreadSupported()
54	{
55	    if (GetHcommVersion() >= CANN_VERSION(9, 0, 0) && HcommIsSupportHcclThreadExportToCommEngine()) {
56	        return true;
57	    } else {
58	        return false;
59	    }
60	}
61	
62	// 初始化
63	void HcommDlInit(void)
64	{
65	    if (gLibHandle != nullptr)
66	        return;
67	
68	    gLibHandle = dlopen("libhcomm.so", RTLD_NOW);
69	    if (!gLibHandle) {
70	        fprintf(stderr, "[HcclWrapper] Failed to open libhcomm: %s\n", dlerror());
71	        return;
72	    }
73	
74	    dlerror();
75	
76	    HcclResDlInit(gLibHandle);
77	    HcclRankGraphDlInit(gLibHandle);
78	    HcommPrimitivesDlInit(gLibHandle);
79	    HcclInnerDlInit(gLibHandle);
80	    HcommProfilingDlInit(gLibHandle);
81	    HcclCommDlInit(gLibHandle);
82	    HcclResExptDlInit(gLibHandle);
83	    CcuResDlInit(gLibHandle);
84	    HcclCcuResDlInit(gLibHandle);
85	    CcuLaunchDlInit(gLibHandle);
86	    CcuPrimitivesImplDlInit(gLibHandle);
87	}
