140	HcclCalcOpResOnlineGraphMode(OpParamGraphMode* opParam, u64* opMemSize, u32* streamNum, u32* taskNum, u32* aivCoreNum)
141	{
142	    HCCL_INFO("Enter HcclCalcOpResOnlineGraphMode.");
143	    CHK_RET(CheckCalcResInputGraphMode(opParam, opMemSize, streamNum, taskNum, aivCoreNum));
144	    // 将void**转换为OpParamGraphMode**
145	    OpParamGraphMode* paramPtr = reinterpret_cast<OpParamGraphMode*>(opParam);
146	    if (paramPtr == nullptr) {
147	        return HCCL_E_PARA;
148	    }
149	    // 为了兼容，创建临时的 ResResponseGraphMode 结构
150	    ResResponseGraphMode resResponse = {0, 0, 0, 0};
151	    HCCL_INFO("Start to calc op resource online.");
152	    // aicpu引擎计算资源
