157	
158	    // aiv引擎计算资源
159	    ops_hccl::HcclCalcAivResOffline(&resResponse, paramPtr);
160	
161	    // 将结果复制到输出参数
162	    *opMemSize = resResponse.opMemSize;
163	    *streamNum = resResponse.streamNum;
164	    *taskNum = resResponse.taskNum;
165	    *aivCoreNum = resResponse.aivCoreNum;
166	
167	    return HCCL_SUCCESS;
