219	HcclResult HcclSelectAlgGraphMode(
220	    const char* group, u64 count, HcclDataType dataType, HcclReduceOp op, HcclCMDType opType, u32 aivCoreLimit,
221	    bool* ifAiv, char* algName)
222	{
223	    if (group == nullptr || ifAiv == nullptr || algName == nullptr) {
224	        HCCL_ERROR("[HcclSelectAlgGraphMode] Invalid parameters");
225	        return HCCL_E_PARA;
226	    }
227	    HCCL_INFO(
228	        "[HcclSelectAlgGraphMode] Start: group[%s] count[%llu] dataType[%u] reduceOp[%u] opType[%u] aivCoreLimit[%u]",
229	        group, count, dataType, op, opType, aivCoreLimit);
230	
231	    if (g_aivKernelInfoMap.find(opType) == g_aivKernelInfoMap.end()) {
232	        HCCL_INFO("[HcclSelectAlgGraphMode] Unsupported aiv op.");
233	        return HCCL_SUCCESS;
234	    }
235	
236	    s32 deviceId = 0;
237	    CHK_PRT_RET(
238	        aclrtGetDevice(&deviceId) != ACL_SUCCESS, HCCL_WARNING("[HcclSelectAlgGraphMode] device is not set."),
239	        HCCL_SUCCESS);
240	
241	    HcclComm hcclComm = nullptr;
242	    CHK_RET(HcomGetCommHandleByGroup(group, &hcclComm));
243	    u32 rankSize = INVALID_VALUE_RANKSIZE;
244	    CHK_RET(HcclGetRankSize(hcclComm, &rankSize));
245	
246	    CHK_RET(InitEnvConfig());
247	
248	    ops_hccl::OpParam param;
249	    CHK_RET(HcclGetCommName(hcclComm, param.commName));
250	
251	    HcclDevType deviceType = HcclDevType::DEV_TYPE_COUNT;
252	    CHK_RET(HcclGetDeviceType(deviceType));
253	
254	    param.opType = opType;
255	    param.DataDes.count = count;
256	    param.DataDes.dataType = dataType;
257	    param.reduceType = op;
258	    param.opMode = ops_hccl::OpMode::OFFLOAD;
259	    param.numBlocksLimit = aivCoreLimit;
260	    param.enableDetour = false;
261	    param.deviceType = deviceType;
262	
263	    AclHostMemGuard sendCountsHost;
264	    AclHostMemGuard recvCountsHost;
265	    AclHostMemGuard sdisplsHost;
266	    AclHostMemGuard rdisplsHost;
267	    if (opType == HcclCMDType::HCCL_CMD_ALLTOALL || opType == HcclCMDType::HCCL_CMD_ALLTOALLV
268	        || opType == HcclCMDType::HCCL_CMD_ALLTOALLVC) {
269	        param.varMemSize = ops_hccl::ALL_TO_ALL_V_VECTOR_NUM * rankSize * sizeof(u64);
270	        param.all2AllVDataDes.sendType = dataType;
271	        param.all2AllVDataDes.recvType = dataType;
272	
273	        u64 arrSize = rankSize * sizeof(u64);
274	        ACLCHECK(aclrtMallocHost(&sendCountsHost.ptr, arrSize));
275	        ACLCHECK(aclrtMallocHost(&recvCountsHost.ptr, arrSize));
276	        ACLCHECK(aclrtMallocHost(&sdisplsHost.ptr, arrSize));
277	        ACLCHECK(aclrtMallocHost(&rdisplsHost.ptr, arrSize));
278	
279	        u64* sendCountsPtr = static_cast<u64*>(sendCountsHost.ptr);
280	        u64* recvCountsPtr = static_cast<u64*>(recvCountsHost.ptr);
281	        u64* sdisplsPtr = static_cast<u64*>(sdisplsHost.ptr);
282	        u64* rdisplsPtr = static_cast<u64*>(rdisplsHost.ptr);
283	
284	        u64 dataCountOffset = 0;
285	        for (u32 i = 0; i < rankSize; i++) {
286	            sendCountsPtr[i] = count;
287	            recvCountsPtr[i] = count;
288	            sdisplsPtr[i] = dataCountOffset;
289	            rdisplsPtr[i] = dataCountOffset;
290	            dataCountOffset += count;
291	        }
292	
293	        param.all2AllVDataDes.sendCounts = sendCountsHost.ptr;
294	        param.all2AllVDataDes.recvCounts = recvCountsHost.ptr;
295	        param.all2AllVDataDes.sdispls = sdisplsHost.ptr;
296	        param.all2AllVDataDes.rdispls = rdisplsHost.ptr;
297	    }
298	
299	    int ret = sprintf_s(param.tag, sizeof(param.tag), "SelectAlg_%d_%s", static_cast<int>(opType), param.commName);
300	    CHK_PRT_RET(ret <= 0, HCCL_ERROR("[HcclSelectAlgGraphMode] failed to fill param.tag"), HCCL_E_INTERNAL);
301	
302	    CHK_RET(ops_hccl::HcclGetOpExpansionMode(hcclComm, param));
303	
304	    std::unique_ptr<ops_hccl::TopoInfoWithNetLayerDetails> topoInfo
305	        = std::make_unique<ops_hccl::TopoInfoWithNetLayerDetails>();
306	    std::string localAlgName;
307	    CHK_RET(ops_hccl::Selector(hcclComm, param, topoInfo, localAlgName));
308	
309	    *ifAiv = (param.engine == CommEngine::COMM_ENGINE_AIV);
310	
311	    // 拷贝字符串
312	    CHK_SAFETY_FUNC_RET(strncpy_s(algName, ALG_NAME_MAX_LEN, localAlgName.c_str(), ALG_NAME_MAX_LEN - 1));
313	
314	    HCCL_INFO("[HcclSelectAlgGraphMode] Success. ifAiv=%d, algName=%s", *ifAiv, algName);
315	    return HCCL_SUCCESS;
316	}
