319	// 图模式下算法选择+录制模式的公共流程，返回录制的aivOpArgs与cclBufferSize
320	HcclResult RecordAivOpArgsGraphMode(
321	    const char* group, u64 count, HcclDataType dataType, HcclReduceOp op, HcclCMDType opType, u32 aivCoreLimit,
322	    void* inputPtr, void* outputPtr, const char* tag, ops_hccl::AivOpArgs& aivOpArgs, u64& cclBufferSize)
323	{
324	    HcclComm comm = nullptr;
325	    CHK_RET(HcomGetCommHandleByGroup(group, &comm));
326	    u32 rankSize = INVALID_VALUE_RANKSIZE;
327	    CHK_RET(HcclGetRankSize(comm, &rankSize));
328	
329	    ops_hccl::OpParam param;
330	    param.hcclComm = comm;
331	    param.opType = opType;
332	    param.inputPtr = inputPtr;
333	    param.outputPtr = outputPtr;
334	    param.DataDes.count = count;
335	    param.DataDes.dataType = dataType;
336	    param.reduceType = op;
337	    param.opMode = ops_hccl::OpMode::OFFLOAD;
338	    param.numBlocksLimit = aivCoreLimit;
339	
340	    AclHostMemGuard sendCountsHost;
341	    AclHostMemGuard recvCountsHost;
342	    AclHostMemGuard sdisplsHost;
343	    AclHostMemGuard rdisplsHost;
344	    if (opType == HcclCMDType::HCCL_CMD_ALLTOALL || opType == HcclCMDType::HCCL_CMD_ALLTOALLV
345	        || opType == HcclCMDType::HCCL_CMD_ALLTOALLVC) {
346	        param.varMemSize = ops_hccl::ALL_TO_ALL_V_VECTOR_NUM * rankSize * sizeof(u64);
347	        param.all2AllVDataDes.sendType = dataType;
348	        param.all2AllVDataDes.recvType = dataType;
349	
350	        u64 arrSize = rankSize * sizeof(u64);
351	        ACLCHECK(aclrtMallocHost(&sendCountsHost.ptr, arrSize));
352	        ACLCHECK(aclrtMallocHost(&recvCountsHost.ptr, arrSize));
353	        ACLCHECK(aclrtMallocHost(&sdisplsHost.ptr, arrSize));
354	        ACLCHECK(aclrtMallocHost(&rdisplsHost.ptr, arrSize));
355	
356	        u64* recvCountsPtr = static_cast<u64*>(recvCountsHost.ptr);
357	        u64* sendCountsPtr = static_cast<u64*>(sendCountsHost.ptr);
358	        u64* sdisplsPtr = static_cast<u64*>(sdisplsHost.ptr);
359	        u64* rdisplsPtr = static_cast<u64*>(rdisplsHost.ptr);
360	
361	        u64 dataCountOffset = 0;
362	        for (u32 i = 0; i < rankSize; i++) {
363	            sendCountsPtr[i] = count;
364	            recvCountsPtr[i] = count;
365	            sdisplsPtr[i] = dataCountOffset;
366	            rdisplsPtr[i] = dataCountOffset;
367	            dataCountOffset += count;
368	        }
369	
370	        param.all2AllVDataDes.recvCounts = recvCountsHost.ptr;
371	        param.all2AllVDataDes.sendCounts = sendCountsHost.ptr;
372	        param.all2AllVDataDes.sdispls = sdisplsHost.ptr;
373	        param.all2AllVDataDes.rdispls = rdisplsHost.ptr;
374	    }
375	
376	    CHK_RET(InitEnvConfig());
377	    HcclDevType deviceType = HcclDevType::DEV_TYPE_COUNT;
378	    CHK_RET(HcclGetDeviceType(deviceType));
379	    param.deviceType = deviceType;
380	
381	    int ret = sprintf_s(param.tag, sizeof(param.tag), "%s", tag);
382	    CHK_PRT_RET(ret <= 0, HCCL_ERROR("[RecordAivOpArgsGraphMode] failed to fill param.tag"), HCCL_E_INTERNAL);
383	    CHK_RET(HcclGetCommName(comm, param.commName));
384	    ret = sprintf_s(param.commModeTag, sizeof(param.commModeTag), "%s_offload", param.commName);
385	    CHK_PRT_RET(ret <= 0, HCCL_ERROR("[RecordAivOpArgsGraphMode] failed to fill param.commModeTag"), HCCL_E_INTERNAL);
386	
387	    CHK_RET(ops_hccl::HcclGetOpExpansionMode(comm, param));
388	
389	    // 算法选择
390	    std::unique_ptr<ops_hccl::TopoInfoWithNetLayerDetails> topoInfo
391	        = std::make_unique<ops_hccl::TopoInfoWithNetLayerDetails>();
392	    std::string algName;
393	    CHK_RET(ops_hccl::Selector(comm, param, topoInfo, algName));
394	
395	    std::unique_ptr<ops_hccl::InsCollAlgBase> executor
396	        = ops_hccl::CollAlgExecRegistryV2::Instance().GetAlgExec(param.opType, algName);
397	    CHK_PRT_RET(
398	        executor.get() == nullptr,
399	        HCCL_ERROR("[RecordAivOpArgsGraphMode] Failed to find executor for algName[%s]", algName.c_str()), HCCL_E_PARA);
400	
401	    // 启用Only录制模式
402	    ops_hccl::g_recordingQueue = std::make_shared<ops_hccl::InsQueue>();
403	    ops_hccl::g_baseInputAddr = reinterpret_cast<u64>(inputPtr);
404	    ops_hccl::g_baseOutputAddr = reinterpret_cast<u64>(outputPtr);
405	    ops_hccl::g_recordOnlyMode = true;
406	
407	    // 计算AlgHierarchyInfo
408	    ops_hccl::AlgHierarchyInfoForAllLevel algHierarchyInfo;
409	    CHK_RET(executor->CalcAlgHierarchyInfo(comm, topoInfo.get(), algHierarchyInfo));
410	    // 资源计算
411	    ops_hccl::AlgResourceRequest resRequest;
412	    CHK_RET(executor->CalcRes(comm, param, topoInfo.get(), algHierarchyInfo, resRequest));
413	    // host侧资源
414	    void* resCtxSequence = nullptr;
415	    CHK_RET(ops_hccl::GetAlgResAiv(comm, param, resRequest, topoInfo.get(), algHierarchyInfo, &resCtxSequence));
416	    // 编排
417	    ops_hccl::AlgResourceCtxSerializable* resCtxHost
418	        = static_cast<ops_hccl::AlgResourceCtxSerializable*>(resCtxSequence);
419	    CHK_RET(executor->Orchestrate(param, *resCtxHost));
420	
421	    // 从录制的指令队列中获取aivOpArgs
422	    if (ops_hccl::g_recordingQueue && !ops_hccl::g_recordingQueue->empty()) {
423	        aivOpArgs = (*ops_hccl::g_recordingQueue)[0].opArgs;
424	    }
425	    cclBufferSize = resCtxHost->cclMem.size;
426	
427	    // 清除录制
428	    ops_hccl::g_recordingQueue = nullptr;
429	    ops_hccl::g_baseInputAddr = 0;
430	    ops_hccl::g_baseOutputAddr = 0;
431	    ops_hccl::g_recordOnlyMode = false;
432	
433	    // 销毁录制期间创建的algTag context，避免相同tag重复注册导致already exist错误
434	    HcclEngineCtxDestroy(comm, param.algTag, CommEngine::COMM_ENGINE_CPU_TS);
435	
436	    return HCCL_SUCCESS;
437	}
