474	        "[HcclGetAlgExecParamGraphMode] tag[%s], group[%s], count[%llu], opType[%d], dataType[%d], "
475	        "reduceOp[%d], clearEnable[%d], aivCoreLimit[%u]",
476	        tag != nullptr ? tag : "nullptr", group != nullptr ? group : "nullptr", count, static_cast<int>(opType),
