500	    superKernelArgs.tag = 0;
501	    superKernelArgs.clearEnable = clearEnable;
502	    superKernelArgs.inputSliceStride = 0;
503	    superKernelArgs.outputSliceStride = 0;
504	    superKernelArgs.repeatNum = 1;
505	    superKernelArgs.inputRepeatStride = 0;
506	    superKernelArgs.outputRepeatStride = 0;
507	    superKernelArgs.input = aivOpArgs.input;
508	    superKernelArgs.output = aivOpArgs.output;
509	    superKernelArgs.cclBufferSize = cclBufferSize;
510	
