512	        "[HcclGetAlgExecParamGraphMode] superKernelArgs: buffersIn[%p], rank[%u], rankSize[%u], "
513	        "len[%llu], dataType[%u], unitSize[%u], reduceOp[%u], numBlocks[%u], tag[%d], "
514	        "clearEnable[%d], inputSliceStride[%llu], outputSliceStride[%llu], repeatNum[%llu], "
515	        "inputRepeatStride[%llu], outputRepeatStride[%llu], input[%p], output[%p], cclBufferSize[%llu]",
516	        superKernelArgs.buffersIn, superKernelArgs.rank, superKernelArgs.rankSize, superKernelArgs.len,
517	        superKernelArgs.dataType, superKernelArgs.unitSize, superKernelArgs.reduceOp, superKernelArgs.numBlocks,
518	        superKernelArgs.tag, superKernelArgs.clearEnable, superKernelArgs.inputSliceStride,
519	        superKernelArgs.outputSliceStride, superKernelArgs.repeatNum, superKernelArgs.inputRepeatStride,
520	        superKernelArgs.outputRepeatStride, superKernelArgs.input, superKernelArgs.output,
521	        superKernelArgs.cclBufferSize);
522	
523	    // 分配设备内存
524	    void* deviceMem = nullptr;
525	    aclError aclRet = aclrtMalloc(&deviceMem, sizeof(ops_hccl::AivSuperKernelArgs), ACL_MEM_MALLOC_HUGE_FIRST);
526	    CHK_PRT_RET(
527	        aclRet != ACL_SUCCESS, HCCL_ERROR("[HcclGetAlgExecParamGraphMode] aclrtMalloc failed, ret[%d]", aclRet),
528	        HCCL_E_RUNTIME);
529	    // 拷贝到设备内存
530	    aclRet = aclrtMemcpy(
531	        deviceMem, sizeof(ops_hccl::AivSuperKernelArgs), &superKernelArgs, sizeof(ops_hccl::AivSuperKernelArgs),
532	        ACL_MEMCPY_HOST_TO_DEVICE);
533	    if (aclRet != ACL_SUCCESS) {
534	        HCCL_ERROR("[HcclGetAlgExecParamGraphMode] aclrtMemcpy failed, ret[%d]", aclRet);
535	        aclError freeRet = aclrtFree(deviceMem);
536	        if (freeRet != ACL_SUCCESS) {
537	            HCCL_ERROR("[HcclGetAlgExecParamGraphMode] aclrtFree failed, ret[%d]", freeRet);
538	        }
539	        return HCCL_E_RUNTIME;
540	    }
541	
542	    *commContext = deviceMem;
543	    *len = sizeof(ops_hccl::AivSuperKernelArgs);
544	
545	    HCCL_INFO("[HcclGetAlgExecParamGraphMode] success, commContext[%p], len[%llu]", *commContext, *len);
546	    return HCCL_SUCCESS;
547	}
