594	{
595	    HCCL_INFO("Entry HcclCalcCcuResOffline.");
596	    if (resResponse == nullptr || opParam == nullptr) {
597	        return HCCL_E_PARA;
598	    }
599	
600	    // ccu的资源申请
601	    u64 ccuOpMemSize = 0;
602	    u32 ccuStreamNum = 6;
603	    u32 ccuTaskNum = 0;
604	
605	    CHK_PRT(CalcTaskNum(opParam, ccuTaskNum));
606	
607	    resResponse->opMemSize = std::max(resResponse->opMemSize, ccuOpMemSize);
608	    resResponse->streamNum = std::max(resResponse->streamNum, ccuStreamNum);
609	    resResponse->taskNum = std::max(resResponse->taskNum, ccuTaskNum);
610	    HCCL_INFO(
611	        "[HcclCalcCcuResOffline] opMemSize[%llu], streamNum[%llu], taskNum[%llu]", resResponse->opMemSize,
612	        resResponse->streamNum, resResponse->taskNum);
613	    return HCCL_SUCCESS;
614	}
615	
616	HcclResult CalcTaskNum(OpParamGraphMode* opParam, u32& ccuTaskNum)
617	{
618	    HCCL_INFO("[CalcTaskNum] begin");
619	    if (opParam->hcclBufferSize == 0 || opParam->rankSize == 0) {
620	        ccuTaskNum = GE_PARALLEL;
621	        return HCCL_SUCCESS;
622	    }
623	
624	    u64 dataCount = opParam->dataCount;
625	    u64 rankSize = opParam->rankSize;
626	    u64 scratchBufferSize = opParam->hcclBufferSize;
627	    u64 transportBoundDataSize = UB_MAX_DATA_SIZE;
628	    u64 dataType = opParam->dataType;
629	    u64 dataTypeSize = DATATYPE_SIZE_TABLE[dataType];
630	    u64 maxDataSizePerLoop = 0;
631	    u64 maxDataCountPerLoop = 0;
632	    u64 loopTimes = 0;
633	    HCCL_INFO(
634	        "[CalcTaskNum] opType[%s] scratchBufferSize[%llu] dataCount[%llu] rankSize[%llu]", opParam->opType,
635	        scratchBufferSize, dataCount, rankSize);
636	    if (opParam->opType == HCCL_KERNEL_OP_TYPE_ALLTOALL) {
637	        maxDataSizePerLoop = transportBoundDataSize;
638	        maxDataCountPerLoop = maxDataSizePerLoop / dataTypeSize / rankSize;
639	        loopTimes = dataCount / maxDataCountPerLoop + static_cast<u64>(dataCount % maxDataCountPerLoop != 0);
640	        ccuTaskNum = loopTimes;
641	    } else if (opParam->opType == HCCL_KERNEL_OP_TYPE_ALLTOALLV || opParam->opType == HCCL_KERNEL_OP_TYPE_ALLTOALLVC) {
642	        ccuTaskNum = 1;
643	    } else if (opParam->opType == HCCL_KERNEL_OP_TYPE_REDUCE) {
644	        maxDataSizePerLoop = std::min(transportBoundDataSize, scratchBufferSize);
645	        maxDataCountPerLoop = maxDataSizePerLoop / dataTypeSize;
646	        loopTimes = dataCount / maxDataCountPerLoop + static_cast<u64>(dataCount % maxDataCountPerLoop != 0);
647	        ccuTaskNum = loopTimes * GE_PARALLEL;
648	    } else if (opParam->opType == HCCL_KERNEL_OP_TYPE_BROADCAST) {
649	        maxDataSizePerLoop = transportBoundDataSize;
650	        maxDataCountPerLoop = maxDataSizePerLoop / dataTypeSize;
651	        loopTimes = dataCount / maxDataCountPerLoop + static_cast<u64>(dataCount % maxDataCountPerLoop != 0);
652	        ccuTaskNum = loopTimes * GE_PARALLEL;
653	    } else if (opParam->opType == HCCL_KERNEL_OP_TYPE_ALLGATHER) {
654	        maxDataSizePerLoop = transportBoundDataSize;
655	        maxDataCountPerLoop = maxDataSizePerLoop / dataTypeSize;
656	        loopTimes = dataCount / maxDataCountPerLoop + static_cast<u64>(dataCount % maxDataCountPerLoop != 0);
657	        ccuTaskNum = loopTimes * GE_PARALLEL;
658	    } else if (opParam->opType == HCCL_KERNEL_OP_TYPE_REDUCESCATTER) {
659	        maxDataSizePerLoop = std::min(transportBoundDataSize, scratchBufferSize);
660	        maxDataCountPerLoop = maxDataSizePerLoop / dataTypeSize;
661	        loopTimes = dataCount / maxDataCountPerLoop + static_cast<u64>(dataCount % maxDataCountPerLoop != 0);
662	        ccuTaskNum = loopTimes * GE_PARALLEL;
663	    } else if (opParam->opType == HCCL_KERNEL_OP_TYPE_ALLREDUCE) {
664	        maxDataSizePerLoop = std::min(transportBoundDataSize, scratchBufferSize);
665	        u64 scratchBoundDataSize = scratchBufferSize / rankSize / 128 * 128;
666	        maxDataSizePerLoop = std::min(transportBoundDataSize, scratchBoundDataSize);
667	        maxDataCountPerLoop = maxDataSizePerLoop / dataTypeSize;
668	        loopTimes = dataCount / maxDataCountPerLoop + static_cast<u64>(dataCount % maxDataCountPerLoop != 0);
669	        ccuTaskNum = loopTimes * GE_PARALLEL;
670	    } else if (opParam->opType == HCCL_KERNEL_OP_TYPE_SCATTER) {
671	        maxDataSizePerLoop = std::min(transportBoundDataSize, scratchBufferSize);
672	        maxDataCountPerLoop = maxDataSizePerLoop / dataTypeSize;
673	        loopTimes = dataCount / maxDataCountPerLoop + static_cast<u64>(dataCount % maxDataCountPerLoop != 0);
674	        ccuTaskNum = loopTimes * GE_PARALLEL;
675	    } else if (opParam->opType == HCCL_KERNEL_OP_TYPE_ALLGATHERV) {
676	        maxDataSizePerLoop = transportBoundDataSize;
677	        maxDataCountPerLoop = maxDataSizePerLoop / dataTypeSize;
678	        loopTimes = dataCount / maxDataCountPerLoop + static_cast<u64>(dataCount % maxDataCountPerLoop != 0);
679	        ccuTaskNum = loopTimes * GE_PARALLEL;
680	    } else if (opParam->opType == HCCL_KERNEL_OP_TYPE_REDUCESCATTERV) {
681	        maxDataSizePerLoop = std::min(transportBoundDataSize, scratchBufferSize);
682	        maxDataCountPerLoop = maxDataSizePerLoop / dataTypeSize;
683	        loopTimes = dataCount / maxDataCountPerLoop + static_cast<u64>(dataCount % maxDataCountPerLoop != 0);
684	        ccuTaskNum = loopTimes * GE_PARALLEL;
685	    }
686	    HCCL_INFO(
687	        "[CalcTaskNum] maxDataSizePerLoop[%llu] maxDataCountPerLoop[%llu] loopTimes[%llu] ccuTaskNum[%llu]",
688	        maxDataSizePerLoop, maxDataCountPerLoop, loopTimes, ccuTaskNum);
689	    HCCL_INFO("[CalcTaskNum] end.");
690	    return HCCL_SUCCESS;
691	}
