175	// Entry Log中u64数组按rank区间分片打印的单片段最大长度，避免触发LOG_TMPBUF_SIZE截断
176	constexpr size_t ENTRY_ARRAY_LOG_CHUNK_SIZE = 384;
177	constexpr u32 ENTRY_ARRAY_LOG_RESERVE_EXTRA = 32; // 预留额外容量
178	constexpr u32 ENTRY_ARRAY_LOG_SEPARATOR_LEN = 2;  // 分隔符长度(", ")
179	
180	// 按rank区间分片打印变长算子Entry Log中的u64数组参数，规避512字节栈缓冲截断
181	inline void PrintEntryArrayLog(
182	    const std::string& opName, const std::string& tag, const char* name, const void* data, u32 totalRanks)
183	{
184	    if (data == nullptr || name == nullptr) {
185	        HCCL_RUN_INFO(
186	            "Entry-%s: tag[%s], %s data is null", opName.c_str(), tag.c_str(), name == nullptr ? "array" : name);
187	        return;
188	    }
189	
190	    if (totalRanks == 0) {
191	        HCCL_RUN_INFO("Entry-%s: tag[%s], %s[empty]", opName.c_str(), tag.c_str(), name);
192	        return;
193	    }
194	
195	    const u64* values = static_cast<const u64*>(data);
196	    std::string chunk;
197	    chunk.reserve(ENTRY_ARRAY_LOG_CHUNK_SIZE + ENTRY_ARRAY_LOG_RESERVE_EXTRA); // 预留容量，避免增长时多次重分配
198	    u32 startRank = 0;
199	
200	    for (u32 i = 0; i < totalRanks; ++i) {
201	        std::string num = std::to_string(values[i]);
202	        // 加入分隔符和当前数值后若超出单片段长度，则先flush当前chunk
203	        if (!chunk.empty() && chunk.size() + ENTRY_ARRAY_LOG_SEPARATOR_LEN + num.size() > ENTRY_ARRAY_LOG_CHUNK_SIZE) {
204	            HCCL_RUN_INFO(
205	                "Entry-%s: tag[%s], %s[%u..%u]/%u=[%s]", opName.c_str(), tag.c_str(), name, startRank, i - 1,
206	                totalRanks, chunk.c_str());
207	            chunk.clear();
208	            startRank = i;
209	            chunk = std::move(num);
210	        } else {
211	            if (!chunk.empty()) {
212	                chunk += ", ";
213	            }
214	            chunk += num;
215	        }
216	    }
217	
218	    if (!chunk.empty()) {
219	        HCCL_RUN_INFO(
220	            "Entry-%s: tag[%s], %s[%u..%u]/%u=[%s]", opName.c_str(), tag.c_str(), name, startRank, totalRanks - 1,
221	            totalRanks, chunk.c_str());
222	    }
223	}
