31	HcclResult AicpuTaskCacheCommManager::EvictTaskCache(HcclComm comm)
32	{
33	    std::vector<std::string> tags;
34	    {
35	        std::unique_lock<std::shared_timed_mutex> lock(mutex_);
36	        auto it = commToTagMap_.find(comm);
37	        if (it == commToTagMap_.end()) {
38	            return HCCL_SUCCESS;
39	        }
40	        tags = std::move(it->second);
41	        commToTagMap_.erase(it);
42	    }
43	
44	    uint32_t failCnt = 0;
45	    if (HcommIsSupportHcommAicpuTsTaskCacheClear()) {
46	        for (const auto& tag : tags) {
47	            HCCL_INFO("[EvictTaskCache] comm[%p] clear cache tag[%s]", comm, tag.c_str());
48	            if (HcommAicpuTsTaskCacheClear(tag.c_str()) != HCCL_SUCCESS) {
49	                HCCL_ERROR("[EvictTaskCache] comm[%p] clear cache tag[%s] failed", comm, tag.c_str());
50	                failCnt++;
51	            }
52	        }
53	    }
54	    if (failCnt > 0) {
55	        HCCL_ERROR("[EvictTaskCache] comm[%p] failed[%u]", comm, failCnt);
56	        return HCCL_E_INTERNAL;
57	    }
58	    return HCCL_SUCCESS;
59	}
