20	    // 将无符号整数转为十进制字符串, 写入ptr
21	    // 返回写入后的指针; uint64_t最大20位数字, 调用方保证缓冲区有足够空间
22	    // 兼容uint32_t和unsigned long long (uint32_t隐式提升为uint64_t)
23	    inline char* UIntToChars(char* ptr, uint64_t val)
24	    {
25	        // uint64_t最大20位数字 (18446744073709551615)
26	        char tmp[20];
27	        char* tp = tmp;
28	
29	        do {
30	            *tp++ = static_cast<char>('0' + val % 10U);
31	            val /= 10U;
32	        } while (val > 0);
33	
34	        // 反转写入目标缓冲区
35	        while (tp > tmp) {
36	            *ptr++ = *--tp;
37	        }
38	        return ptr;
39	    }
40	} // namespace
