42	HcclResult AicpuTaskCacheKey::GetAicpuTaskCacheTag(const OpParam& param, uint64_t inputSize, std::string& cacheTag)
43	{
44	    // 暂时不考虑v类算子 (应该被cache使能约束拦截, 不应该进入本函数), dataType一定不是reserved
45	    const HcclCMDType opType = param.opType;
46	    HcclDataType dataType = HcclDataType::HCCL_DATA_TYPE_RESERVED;
47	    if (opType == HcclCMDType::HCCL_CMD_ALLTOALL) { // alltoall算子
48	        dataType = param.all2AllDataDes.sendType;
49	    } else if (AicpuTaskCacheUtils::IsNonVariableOpType(opType)) { // 非alltoall的非v类算子
50	        dataType = param.DataDes.dataType;
51	    } else {
52	        HCCL_ERROR("[AicpuTaskCacheKey][AicpuTaskCacheKey] invalid opType[%d] for aicpu task cache", opType);
53	        return HCCL_E_PARA;
54	    }
55	
56	    // 获取rootRank
57	    // 注意: broadcast/reduce/scatter的task编排受rootRank影响
58	    uint32_t rootRank = 0;
59	    if (opType == HcclCMDType::HCCL_CMD_BROADCAST || opType == HcclCMDType::HCCL_CMD_SCATTER
60	        || opType == HcclCMDType::HCCL_CMD_REDUCE) {
61	        rootRank = param.root;
62	    }
63	
64	    // 获取其他字段
65	    const HcclReduceOp reduceType = param.reduceType;
66	    const bool isZeroCopy = param.isZeroCopy;
67	    const OpMode opMode = param.opMode;
68	
69	    // 使用'-'作为间隔符, 拼接cacheTag
70	    // 注意: 把input size放在前面, 如果需要解析, 可以减少解析开销
71	    // 注意: commId放在最后, 如果需要解析, 无需考虑commId中含有delimiter的情况
72	    // 注意: enum class不能转为uint8_t, 否则会作为char输出; 需显式转为uint32_t后再用to_chars, 否则编译失败
73	    const char* commId = param.commName;  // 最大长度COMM_INDENTIFIER_MAX_LENGTH (128)
74	    constexpr size_t RESERVED_SIZE = 256; // commId+7个整数, 最多128+80+7个字符, 预留256足够
75	    char buf[RESERVED_SIZE];
76	    char* ptr = buf;
77	    const char delimiter = '-';
78	
79	    // inputSize (uint64最多20个字符)
80	    ptr = UIntToChars(ptr, static_cast<unsigned long long>(inputSize));
81	    *ptr++ = delimiter;
82	
83	    // opType (uint32最多10个字符)
84	    ptr = UIntToChars(ptr, static_cast<uint32_t>(opType));
85	    *ptr++ = delimiter;
86	
87	    // dataType (uint32最多10个字符)
88	    ptr = UIntToChars(ptr, static_cast<uint32_t>(dataType));
89	    *ptr++ = delimiter;
90	
91	    // reduceType (uint32最多10个字符)
92	    ptr = UIntToChars(ptr, static_cast<uint32_t>(reduceType));
93	    *ptr++ = delimiter;
94	
95	    // isZeroCopy (uint32最多10个字符)
96	    ptr = UIntToChars(ptr, static_cast<uint32_t>(isZeroCopy));
97	    *ptr++ = delimiter;
98	
99	    // opMode (uint32最多10个字符)
100	    ptr = UIntToChars(ptr, static_cast<uint32_t>(opMode));
101	    *ptr++ = delimiter;
102	
103	    // rootRank (uint32最多10个字符)
104	    ptr = UIntToChars(ptr, rootRank);
105	    *ptr++ = delimiter;
106	
107	    // 拼接commId (最后一段, 不加delimiter后缀; 最多128个字符)
108	    size_t commLen = std::strlen(commId);
109	    // commId最大长度为COMM_INDENTIFIER_MAX_LENGTH, 不会失败
110	    (void)memcpy_s(ptr, COMM_INDENTIFIER_MAX_LENGTH, commId, commLen);
111	    ptr += commLen;
112	
113	    // 重新更新cacheTag长度
114	    cacheTag.assign(buf, static_cast<size_t>(ptr - buf));
115	
116	    HCCL_INFO(
117	        "[AicpuTaskCacheKey][GetAicpuTaskCacheTag] cacheTag[%s] from commId[%s] opType[%d] dataType[%d] "
118	        "reduceType[%d] isZeroCopy[%d] inputSize[%llu] opMode[%d] rootRank[%d]",
119	        cacheTag.c_str(), commId, opType, dataType, reduceType, isZeroCopy, inputSize, opMode, rootRank);
120	
121	    return HCCL_SUCCESS;
122	}
