18	HcclResult AicpuTaskCachePolicy::IsAicpuTaskCacheEnable(
19	    const OpParam& param, const AlgResourceCtxSerializable& resCtx, bool& isCacheEnable)
20	{
21	    isCacheEnable = false;
22	    if (!param.aicpuCacheEnable) {
23	        HCCL_INFO("[AicpuTaskCachePolicy][IsAicpuTaskCacheEnable] AICPU_CacheDisable is not supported");
24	        return HCCL_SUCCESS;
25	    }
26	
27	    if (param.deviceType != HcclDevType::DEV_TYPE_950) {
28	        HCCL_INFO("[AicpuTaskCachePolicy][IsAicpuTaskCacheEnable] deviceType[%d] is not supported", param.deviceType);
29	        return HCCL_SUCCESS;
30	    }
31	
32	    // MC2算子不支持
33	    if (param.isMc2) {
34	        HCCL_INFO("[AicpuTaskCachePolicy][IsAicpuTaskCacheEnable] mc2 is not supported");
35	        return HCCL_SUCCESS;
36	    }
37	
38	    // 图模式不支持
39	    if (param.opMode == OpMode::OFFLOAD) {
40	        HCCL_INFO("[AicpuTaskCachePolicy][IsAicpuTaskCacheEnable] OpMode::OFFLOAD is not supported");
41	        return HCCL_SUCCESS;
42	    }
43	
44	    // aclgraph 不支持
45	    if (param.isCapture) {
46	        HCCL_INFO("[AicpuTaskCachePolicy][IsAicpuTaskCacheEnable] aclgraph is not supported");
47	        return HCCL_SUCCESS;
48	    }
49	
50	    // 校验算子类型
51	    if (!IsOpTypeSupported(param)) {
52	        return HCCL_SUCCESS;
53	    }
54	
55	    // 屏蔽inplace场景
56	    bool isInplace = false;
57	    CHK_RET(IsInplaceForCache(param, resCtx.topoInfo.userRankSize, isInplace));
58	    if (isInplace) {
59	        HCCL_INFO("[AicpuTaskCachePolicy][IsAicpuTaskCacheEnable] inplace case is not supported for operator unfolding "
60	                  "cache");
61	        return HCCL_SUCCESS;
62	    }
63	
64	    if (!IsTopoSupported(resCtx)) {
65	        return HCCL_SUCCESS;
66	    }
67	
68	    // 所有使能判断都通过是返回true
69	    isCacheEnable = true;
70	    return HCCL_SUCCESS;
71	}
