73	HcclResult AicpuTaskCachePolicy::IsInplaceForCache(const OpParam& param, const uint32_t rankSize, bool& isInplace)
74	{
75	    // 准备input/output size
76	    uint64_t inputSize = 0;
77	    uint64_t outputSize = 0;
78	
79	    CHK_RET(AicpuTaskCacheUtils::GetInputOutputInfoForCache(param, rankSize, inputSize, outputSize));
80	
81	    // 注意: A3下alltoall/alltoallv/alltoallvc可能存在inputSize/outputSize为0的情况, 导致不分配user input/output
82	    //     但会使用tinySendRecvMem_更新algResource.paramInput/OutputMem用于建链, 导致cache无法区分给定地址字段的地址类型
83	    //     参考aicpu_communicator.cc中的SetAlltoAllInputAndOutPutMem
84	    // 注意: 这里继承A3, 不支持同时为0的场景
85	    if (inputSize == 0 && outputSize == 0) {
86	        isInplace = true;
87	        HCCL_INFO(
88	            "[AicpuTaskCachePolicy][IsInplace] inputSize[%llu] is overlapping with outputSize[%llu] -> isInplace[%d]",
89	            inputSize, outputSize, isInplace);
90	        return HCCL_SUCCESS;
91	    }
92	
93	    // 注意: 如果inputSize和outputSize只有一个为0, 则一定是outplace场景
94	    if (inputSize == 0 || outputSize == 0) {
95	        isInplace = false;
96	        HCCL_INFO(
97	            "[AicpuTaskCachePolicy][IsInplace] inputSize[%llu] is not overlapping with outputSize[%llu] -> "
98	            "isInplace[%d]",
99	            inputSize, outputSize, isInplace);
100	        return HCCL_SUCCESS;
101	    }
102	
103	    const uint64_t inputStart = reinterpret_cast<uint64_t>(param.inputPtr);
104	    const uint64_t inputEnd = inputStart + inputSize - 1;
105	    const uint64_t outputStart = reinterpret_cast<uint64_t>(param.outputPtr);
106	    const uint64_t outputEnd = outputStart + outputSize - 1;
107	
108	    // 对于broadcast算子, UserInput与UserOutput完全重叠, 需要按照outplace场景特殊处理, 正常使能cache
109	    if (param.opType == HcclCMDType::HCCL_CMD_BROADCAST) {
110	        CHK_PRT_RET(
111	            !(inputStart == outputStart && inputSize == outputSize),
112	            HCCL_ERROR(
113	                "[AicpuTaskCachePolicy][IsInplace] broadcast should input==output[0x%016llx, 0x%016llx] "
114	                "inputSize==outputSize[%llu,%llu]",
115	                inputStart, outputStart, inputSize, outputSize),
116	            HCCL_E_PARA);
117	        isInplace = false;
118	        HCCL_INFO(
119	            "[AicpuTaskCachePolicy][IsInplace] input==output[0x%016llx, 0x%016llx] for opType[%d] -> isInplace[%d]",
120	            inputStart, inputEnd, param.opType, isInplace);
121	        return HCCL_SUCCESS;
122	    }
123	
124	    if (inputStart <= outputEnd && outputStart <= inputEnd) {
125	        isInplace = true;
126	        HCCL_INFO(
127	            "[AicpuTaskCachePolicy][IsInplace] input[0x%016llx, 0x%016llx] is overlapping with output[0x%016llx, "
128	            "0x%016llx] -> isInplace[%d]",
129	            inputStart, inputEnd, outputStart, outputEnd, isInplace);
130	    } else {
131	        isInplace = false;
132	        HCCL_INFO(
133	            "[AicpuTaskCachePolicy][IsInplace] input[0x%016llx, 0x%016llx] is not overlapping with "
134	            "output[0x%016llx, 0x%016llx] -> isInplace[%d]",
135	            inputStart, inputEnd, outputStart, outputEnd, isInplace);
136	    }
137	
138	    return HCCL_SUCCESS;
139	}
