141	bool AicpuTaskCachePolicy::IsTopoSupported(const AlgResourceCtxSerializable& resCtx)
142	{
143	#if CANN_VERSION_NUM >= CANN_VERSION(9, 1, 0)
144	    for (const auto& levelChannels : resCtx.channels) {
145	        for (const auto& channel : levelChannels) {
146	            if (!channel.isValid) {
147	                continue;
148	            }
149	
150	            // 只支持基于UB的跨卡通信 (当前aicpu仅支持UBC_CTP/UBC_TP/UBOE)
151	            // 不支持其他通信方式, 例如基于外置网卡的跨超RDMA, 基于PCIe的跨卡P2P等
152	            if (channel.protocol != CommProtocol::COMM_PROTOCOL_UBC_CTP
153	                && channel.protocol != CommProtocol::COMM_PROTOCOL_UBC_TP
154	                && channel.protocol != CommProtocol::COMM_PROTOCOL_UBOE) {
155	                HCCL_INFO(
156	                    "[AicpuTaskCachePolicy][IsTopoSupported] found channel protocol[%d] not supported",
157	                    channel.protocol);
158	                return false;
159	            }
160	        }
161	    }
162	    return true;
163	#else
164	    // 小于9.1.0版本，不支持aicpu task cache，直接返回false;
165	    (void)resCtx;
166	    return false;
167	#endif
168	}
169	
170	bool AicpuTaskCachePolicy::IsOpTypeSupported(const OpParam& param)
171	{
172	    // 目前V类算子、batch类型算子、以及send/recv不考虑动态缓存 (使用白名单而非黑名单管理, 避免非预期算子进入cache机制)
173	    // 注意: 当前hccl不支持HcclGather
174	    HcclCMDType opType = param.opType;
175	    if (opType == HcclCMDType::HCCL_CMD_BROADCAST || opType == HcclCMDType::HCCL_CMD_ALLGATHER
176	        || opType == HcclCMDType::HCCL_CMD_ALLTOALL || opType == HcclCMDType::HCCL_CMD_SCATTER) { // 非V类算子
177	        HCCL_INFO(
178	            "[AicpuTaskCachePolicy][IsOpTypeSupported] opType[%d] is supported for operator unfolding cache", opType);
179	        return true;
180	    }
181	
182	    if (opType == HcclCMDType::HCCL_CMD_ALLREDUCE || opType == HcclCMDType::HCCL_CMD_REDUCE
183	        || opType == HcclCMDType::HCCL_CMD_REDUCE_SCATTER) {
184	        HcclDataType dataType = param.DataDes.dataType;
185	        // all_reduce/reduce/reduce_scatter在64位数据类型(INT64/UINT64/FP64)或PROD规约操作时,
186	        // 需要在aicpu上执行reduce操作，不支持aicpu task cache
187	        if (dataType == HcclDataType::HCCL_DATA_TYPE_INT64 || dataType == HcclDataType::HCCL_DATA_TYPE_UINT64
188	            || dataType == HcclDataType::HCCL_DATA_TYPE_FP64 || param.reduceType == HcclReduceOp::HCCL_REDUCE_PROD) {
189	            HCCL_INFO(
190	                "[AicpuTaskCachePolicy][IsOpTypeSupported] opType[%d] is not supported, dataType[%d] "
191	                "reduceOp[%d]",
192	                opType, dataType, param.reduceType);
193	            return false;
194	        } else {
195	            HCCL_INFO(
196	                "[AicpuTaskCachePolicy][IsOpTypeSupported] opType[%d] is supported for operator unfolding cache",
197	                opType);
198	            return true;
199	        }
200	    }
201	
202	    // 其它算子不支持
203	    HCCL_INFO("[AicpuTaskCachePolicy][IsOpTypeSupported] opType[%d] is not supported", param.opType);
204	    return false;
205	}
