26	static ge::graphStatus HcomAllReduceInferShapeV2(gert::InferShapeContext* context)
27	{
28	    OP_INFER_SHAPE_START;
29	
30	    const auto inputShape = context->GetInputShape(0);
31	    OP_CHECK(inputShape == nullptr, CUBE_INNER_ERR_REPORT(opName, "input shape is null"), return GRAPH_FAILED);
32	    auto outputShape = context->GetOutputShape(0);
33	    OP_CHECK(outputShape == nullptr, CUBE_INNER_ERR_REPORT(opName, "output shape is null"), return GRAPH_FAILED);
34	    uint32_t inputSize = context->GetComputeNodeInputNum();
35	
36	    OP_LOGD(opName, "[%s] the op  inputSize %u ", __func__, inputSize);
37	    for (uint32_t index = 0; index < inputSize; index++) {
38	        const auto inputShape = context->GetInputShape(index);
39	        OP_CHECK(inputShape == nullptr, CUBE_INNER_ERR_REPORT(opName, "input shape is null"), return GRAPH_FAILED);
40	        auto outputShape = context->GetOutputShape(index);
41	        OP_CHECK(outputShape == nullptr, CUBE_INNER_ERR_REPORT(opName, "output shape is null"), return GRAPH_FAILED);
42	        *outputShape = *inputShape;
43	    }
44	
45	    OP_INFER_SHAPE_END;
46	    return GRAPH_SUCCESS;
47	}
