49	static ge::graphStatus HcomAllReduceInferDataTypeV2(gert::InferDataTypeContext* context)
50	{
51	    OP_INFER_DATATYPE_START;
52	
53	    uint32_t inputSize = context->GetComputeNodeInputNum();
54	
55	    OP_LOGD(opName, "[%s] the op  inputSize %u ", __func__, inputSize);
56	    for (uint32_t index = 0; index < inputSize; index++) {
57	        ge::DataType inputType = context->GetInputDataType(index);
58	        context->SetOutputDataType(index, inputType);
59	    }
60	
61	    OP_INFER_DATATYPE_END;
62	    return GRAPH_SUCCESS;
63	}
