70	inline ge::graphStatus
71	CheckOPAttr(const ge::char_t* opName, const gert::RuntimeAttrs* attrs, size_t fusionIndex, size_t fusionIdIndex)
72	{
73	    OP_CHECK(attrs == nullptr, CUBE_INNER_ERR_REPORT(opName, "attrs is null"), return ge::GRAPH_FAILED);
74	
75	    constexpr int64_t fusionAttrNoFuse = 0;
76	    constexpr int64_t fusionAttrFuseById = 2;
77	    constexpr int64_t fusionIdDefaultVal = -1;
78	    constexpr int64_t fusionIdMinVal = 0;
79	    constexpr int64_t fusionIdMaxVal = 0x7fffffff;
80	
81	    int64_t fusionAttr = fusionAttrNoFuse;
82	    int64_t fusionIdAttr = fusionIdDefaultVal;
83	
84	    if ((attrs->GetAttrPointer<int64_t>(fusionIndex)) != nullptr) {
85	        fusionAttr = *((attrs->GetAttrPointer<int64_t>(fusionIndex)));
86	    }
87	    if (attrs->GetAttrPointer<int64_t>(fusionIdIndex) != nullptr) {
88	        fusionIdAttr = *(attrs->GetAttrPointer<int64_t>(fusionIdIndex));
89	    }
90	
91	    if ((fusionAttr != fusionAttrNoFuse) && (fusionAttr != fusionAttrFuseById)) {
92	        OP_LOGE(
93	            opName, "Attr fusion [%ld] is not supported. expected: [%ld or %ld]", fusionAttr, fusionAttrNoFuse,
94	            fusionAttrFuseById);
95	        return ge::GRAPH_FAILED;
96	    }
97	    if (fusionAttr == fusionAttrFuseById) {
98	        if ((fusionIdAttr < fusionIdMinVal) || (fusionIdAttr > fusionIdMaxVal)) {
99	            OP_LOGE(
100	                opName,
101	                "In fusion [%ld], attr fusion_id [%ld] is not supported, "
102	                "expected: [%ld ~ %ld]",
103	                fusionAttr, fusionIdAttr, fusionIdMinVal, fusionIdMaxVal);
104	            return ge::GRAPH_FAILED;
105	        }
106	    }
107	
108	    return ge::GRAPH_SUCCESS;
109	}
